import { describe, expect, it } from 'vitest'
import { mount } from '@vue/test-utils'
import Panel from '../Panel.vue'

describe('Panel', () => {
  it('renders the heading and default slots', () => {
    const wrapper = mount(Panel, {
      slots: {
        heading: '<h2>Invoices</h2>',
        default: '<p>3 unpaid invoices</p>',
      },
    })

    expect(wrapper.get('h2').text()).toBe('Invoices')
    expect(wrapper.text()).toContain('3 unpaid invoices')
  })

  it('shows the fallback when the heading slot is empty', () => {
    expect(mount(Panel).text()).toContain('Untitled panel')
  })
})

